#include <stdio.h>
int main(void)
{
    int a[3][3]={{0,1,1},{0,0,1},{0,0,0}}, indegree[3]={0},q[3],h=0,t=0,order[3]={0},count=0;
    for(int u=0;u<3;u++) {
        for(int v=0;v<3;v++) { indegree[v]+=a[u][v]; }
    }
    for(int u=0;u<3;u++) { if(!indegree[u]) { q[t++]=u; } }
    while(h<t) {
        int u=q[h++];order[count++]=u;
        for(int v=0;v<3;v++) {
            if(a[u][v] && --indegree[v]==0) { q[t++]=v; }
        }
    }
    (void)order;
    printf("%d\n",count);
    return 0;
}

